class AppExtension(models.Model):
    app = models.ForeignKey(App, on_delete=models.CASCADE, related_name="extensions")
    label = models.CharField(max_length=256)
    url = models.URLField()
    mount = models.CharField(choices=AppExtensionMount.CHOICES, max_length=256)
    target = models.CharField(
        choices=AppExtensionTarget.CHOICES,
        max_length=128,
        default=AppExtensionTarget.POPUP,
    )
    permissions = models.ManyToManyField(
        Permission,
        blank=True,
        help_text="Specific permissions for this app extension.",
    )
    http_target_method = models.CharField(
        blank=False,
        null=True,
        choices=AppExtensionHttpMethod.CHOICES,
    )


class AppInstallation(Job):
    uuid = models.UUIDField(unique=True, default=uuid4)
    app_name = models.CharField(max_length=60)
    manifest_url = models.URLField()
    permissions = models.ManyToManyField(
        Permission,
        blank=True,
        help_text="Specific permissions which will be assigned to app.",
        related_name="app_installation_set",
        related_query_name="app_installation",
    )
    brand_logo_default = models.ImageField(
        upload_to="app-installation-brand-data", blank=True, null=True
    )

    def set_message(self, message: str, truncate=True):
        if truncate:
            message_field = cast(models.Field, self._meta.get_field("message"))
            max_length = message_field.max_length
            if max_length is None:
                raise ValueError("Cannot truncate message without max_length")
            message = Truncator(message).chars(max_length)
        self.message = message
        types = (AppExtensionOptionsWidget, AppExtensionOptionsNewTab)


class AppExtension(AppManifestExtension, ModelObjectType[models.AppExtension]):
    id = graphene.GlobalID(required=True, description="The ID of the app extension.")
    app = graphene.Field(
        "saleor.graphql.app.types.App",
        required=True,
        description="The app assigned to app extension.",
    )
    access_token = graphene.String(
        description="JWT token used to authenticate by third-party app extension."
    )
    options = graphene.Field(
        AppExtensionPossibleOptions,
        description="App extension options." + ADDED_IN_322,
    )

    class Meta:
        description = "Represents app data."
        interfaces = [graphene.relay.Node]
        model = models.AppExtension

    @staticmethod
    def resolve_url(root, info: ResolveInfo):
        return (
            AppByIdLoader(info.context)
            .load(root.app_id)
            .then(
                lambda app: AppManifestExtension.resolve_url(
                    {"target": root.target, "app_url": app.app_url, "url": root.url},
                    info,
                )
            )
        )

    @staticmethod
    def resolve_target(root, _info: ResolveInfo):
        return root.target

    @staticmethod
    @app_promise_callback
    def resolve_app(root, info: ResolveInfo, app_requestor):
        # Resolve if app from context is the same as requested app
        if app_requestor and app_requestor.id == root.app_id:
            return AppByIdLoader(info.context).load(root.app_id)

        # Reject if app from context is different from requested app
        if app_requestor and app_requestor.id != root.app_id:
            raise PermissionDenied(permissions=[AuthorizationFilters.OWNER])
